fn bs_core(xs: List[Int], x: Int, base: Int) -> Option[Int]
  requires strictly_ascending(xs) and base >= 0
  ensures result == None or (exists i in 0..len(xs): result == Some(base + i) and xs[i] == x)
  ensures (result == None) == (not contains(xs, x))
  effects pure
  example bs_core([1, 4, 6, 9], 6, 0) == Some(2)
  example bs_core([1, 4, 6, 9], 5, 0) == None
